  "rewards.reviewV3.error.save": "Spremanje nije potvrđeno. Ponovno učitaj evidentirano pravilo prije novog pokušaja.",
  "rewards.published.title": "Rezultati → prijedlog nagrada",
  "rewards.pilot.notice": "Izmišljeni pilot s 20 natjecatelja. Ovi testni rezultati nisu kopirani iz stvarnih utrka. Iznosi su prijedlozi, a ne uplaćena sredstva ili isplate. Nisu izrađeni računi ni novčanici natjecatelja niti je pokrenut rok pregleda.",
  "rewards.pilot.categories": "Sedam testnih kategorija natjecatelja i četiri testna kluba. Udjeli kategorija i težine mjesta prijedlozi su koje možeš urediti. Fondovi petog kola i lige ostaju rezervirani do pripreme njihovih rezultata i odobrenja.",
  "rewards.pilot.provenance": "Nepromjenjiv izmišljeni izvor spremljen u demo bazi. Identifikatori ne preuzimaju stvarne profile natjecatelja. Vrijeme simulirane objave označava izradu testnih podataka, a ne završen rok prigovora. Zamrzavanje V2 nije dostupno za ovaj izvor.",
  "rewards.pilot.reviewTitle": "Pregled izmišljenog izvora pilota · V3",
  "rewards.pilot.reviewHelp": "Pregledaj izmišljene testne rezultate ovog kola. Potvrda sada bilježi odluku o izvoru; ne potvrđuje stvarnu utrku, ne pokreće ni završava rok prigovora te ne odobrava ni isplaćuje nagrade.",
  "rewards.pilot.simulatedPublication": "Simulirana objava · testni podaci",
  "rewards.pilot.confirm": "Pregledao/la sam ove točno navedene izmišljene rezultate pilota. Razumijem da to nije stvarno sportsko odobrenje, završen rok prigovora ni odobrenje nagrada.",
