  "rewards.saved.otherWorkspace": "Ovaj spremljeni program pripada organizaciji {organization}, a ne trenutačno odabranom radnom prostoru. Promijeni organizaciju za pregled ovdje. Postavke i nagrade neće se promijeniti.",
  "rewards.saved.switchWorkspace": "Prijeđi na {organization}",
  "rewards.published.notice": "Objavljeni sportski podaci kopirani u ovaj privatni demo. Iznosi su neodobreni prijedlozi, a ne saldo ili isplaćene nagrade. Pregled nije započeo. Nisu izrađeni računi ni novčanici natjecatelja.",
  "rewards.published.categoryGap": "Potvrđen opseg demoa: sedam objavljenih kategorija natjecatelja. Duga staza ima Female i Male; kratka ima i U16 te seniore. Nema zasebne seniorske kategorije duge staze. Točne udjele kategorija odobri zasebno; stvarna liga ostaje nepromijenjena.",
