  "rewards.rehearsal.cohort.help": "Zaseban mali probni scenarij: 20 ponavljajućih sintetičkih natjecatelja, sedam kategorija i četiri kluba. Pet kola sadrži 100 prijava i 97 završetaka, uključujući primjere odustajanja, nedolaska i diskvalifikacije. Ligi pripada 50 MON, a svakom kolu 10 MON. Ovaj zaslon samo izračunava raspodjelu; ne potvrđuje uplate niti šalje nagrade. Veći program ostaje nepromijenjen.",
  "rewards.rehearsal.notice": "Svi rezultati, poretci i reference primatelja ovdje su izmišljeni testni podaci. Ovo nije uvezena liga, stvarni rezultati Šubićevca, spremljena raspodjela ni potvrđeno stanje novčanika. Ništa nije odobreno ni isplaćeno.",
  "rewards.rehearsal.presets": "Predložak: {budget} testnih MON → {league} za ligu + pet fondova po {round} za kola. Svako kolo: 80% natjecatelji / 20% klubovi. Liga: 50% natjecatelji / 20% klubovi / 30% udaljenost. Sedam približno jednakih kategorija natjecatelja uz točno zaokruživanje baznih bodova. Ovo ne mijenja spremljeni nacrt.",
