  "rewards.rehearsal.ranks": "Nagrade koriste službene plasmane kategorije: prvih 10 u kolu, prvih 25 u ligi. Poredak lige u ovoj probi namjerno se razlikuje od poretka kola. Izjednačeni dijele zauzeta mjesta; prazna mjesta zadržavaju iznose. Broj sintetičkih klubova: {clubs}; mjesta lige {unusedFrom}–25 ostaju neiskorištena.",
