  "rewards.rehearsal.scoringPolicy": "Primjer bodovanja koristi isti izračun kao portal: najboljih {best} kola, najmanje {minimum} završene utrke za poredak lige i najboljih {members} natjecatelja svakog kluba po kolu s obje duljine. Svih pet završenih kola i dalje ulazi u nagradu za udaljenost. Tablice bodova u nastavku služe demonstraciji, nisu odobrena pravila Ši Trail lige. Izračun nije službena objava ni odobrenje nagrada.",
