  "rewards.rehearsal.distanceHelp": "Nagrada = fond udaljenosti × završeni metri natjecatelja / svi završeni metri kroz pet konačnih kola, uz determinističko zaokruživanje na cijeli wei. DNS/DNF/DSQ ne dodaju metre. Nedostajući ili nejasan izvor zadržava cijeli nazivnik. Novčanik i preuzimanje profila ne mijenjaju udjele.",
