  "rewards.rehearsal.paymentGate": "Ovdje nema radnje isplate. Stvarna raspodjela još zahtijeva provjerene konačne rezultate i pregled, točno odobrenje organizatora, financirane ugovore, provjeren identitet primatelja i suglasnost novčanika. Udjeli U16, nepoznate dobi i nepreuzetih profila ostaju rezervirani. Sažeci izvora u ovoj probi nisu Merkle dokazi ni potvrđena odobrenja.",
