  "rewards.pilot.planningEvidence": "Ovaj graf prikazuje spremljena pravila nagrada, a ne trenutačna stanja novčanika ili isplaćene nagrade. Opažena stanja provjeri u Financiranju programa, a točne potvrde transakcija u kontrolama izvršavanja ili nagradama natjecatelja.",
  "rewards.planner.funding": "Financiranje: nije potvrđeno",
  "rewards.planner.contract": "Ugovor: nije povezan s ovim nacrtom",
  "rewards.planner.payments": "Isplate: nema povezanih potvrda",
  "rewards.planner.curveTitle": "Udio nagrade prema osvojenom mjestu",
  "rewards.planner.curveHelp": "Primjenjuje se unutar svake odobrene kategorije ili fonda za klupski poredak. Ovo su mjesta za nagrade, a ne nagrade imenovanim primateljima.",
  "rewards.planner.place": "Mjesto",
  "rewards.planner.share": "Udio",
  "rewards.planner.rule.programme": "Početni plan iznosi 100.000 testnih MON: polovica za ligu, a polovica za pet kola. Promjene pregleda nisu odobrene upute za financiranje. Mrežne naknade plaćaju se zasebno.",
  "rewards.planner.rule.race": "Pet zasebnih fondova kola. Predloženi udjeli mogu se urediti; svako završeno kolo treba vlastiti odobreni izvor i pregled raspodjele.",
  "rewards.planner.rule.league": "Demo sezona od pet kola završava nakon Šubićevca. Ligaške nagrade obuhvaćaju službeni konačni poredak, klupski poredak i sudjelovanje prema završenoj udaljenosti.",
  "rewards.planner.rule.round": "Svako kolo ima fondove za poredak natjecatelja i klubova. Unutarnji udjeli su prijedlog; povezivanje kategorija i iznosi trebaju odobrenje. Bonusi za rekorde nisu uključeni.",
  "rewards.planner.rule.athleteStandings": "Nagrade kola obuhvaćaju prvih 10, a ligaške prvih 25 mjesta. Prihvatljivost određuju službene kategorije i poredak. Prazna mjesta zadržavaju neiskorišteni dio; nepreuzeti profili ne gube nagrade.",
  "rewards.planner.rule.clubStandings": "Klupske nagrade koriste odobreni klupski poredak i vlastiti fond. Ne oduzimaju se od nagrada natjecatelja. Klub bez potvrđenog novčanika zadržava ostvareni udio.",
  "rewards.planner.rule.participation": "Svaki natjecatelj dobiva dio fonda sudjelovanja razmjeran svojim službenim završenim metrima u odnosu na sve prihvatljive završene metre u pet kola. Nepreuzeti profili i natjecatelji bez novčanika zadržavaju svoj dio.",
  "rewards.planner.evidence.round": "Nagrade moraju biti povezane s odobrenim službenim završecima utrka, pripadnošću kategoriji i poretkom natjecatelja ili kluba. Ovaj pregled ne izmišlja kategorije ni primatelje.",
  "rewards.planner.evidence.league": "Konačni poredak i službene završene udaljenosti trebaju odobrene dokaze iz svih pet kola. Spremnost novčanika ne smije mijenjati sportsku prihvatljivost.",
  "rewards.planner.evidence.replacement": "Šubićevac zamjenjuje otkazani Zlarin kao završno kolo 3. listopada 2026. Točno povezivanje događaja, ruta i kategorija još nije potvrđeno; ne preuzimaju se Zlarinovi identifikatori.",
