  "rewards.canary.variant.v3": "V3 · Odobrenje konačnih rezultata · 0,1 MON",
  "rewards.canary.variant.v2": "V2 · Izvorni pokus s rokom od 24 h · 1 MON",
  "rewards.canary.v3Policy": "Novi model provjere: organizator unaprijed određuje rok za prigovore na portalu. Konačni rezultati i točna raspodjela moraju biti odobreni prije aktivacije, bez dodatnog obveznog čekanja na lancu. Ovaj sintetički pokus izričito koristi rok od nula sati.",
  "rewards.canary.v2Policy": "Raniji pokus: ovaj zasebni ugovor zadržava izvorni nepromjenjivi rok od 24 sata na lancu. Promjena prikaza ne premješta sredstva niti mijenja ugovore.",
  "rewards.canary.v3NotApproved": "Konačna objava i odobrenje raspodjele još nisu zabilježeni u ovom ugovoru.",
  "rewards.canary.v3Approved": "Zabilježena konačna objava: {published} · Raspodjela odobrena: {approved} (Europe/Zagreb).",
  "rewards.canary.v3Trust": "Ugovor se oslanja na operaterovu potvrdu konačnih rezultata; ne može sam provjeriti sportske rezultate ni prigovore. Aktivacija je zasebna transakcija i ne isplaćuje nagrade automatski.",
  "rewards.canary.executionBoundary": "Planirani udjeli odvojeni su od stvarnih iznosa iznad. Financiranje i aktivacija prolaze kroz kontrolirani operaterski postupak uz provjeru izvornog koda; ova stranica ne šalje transakcije. Prije isplate i dalje su potrebni dokaz upravljanja novčanikom i pristanak primatelja.",
  "rewards.canary.refresh": "Osvježi",
  "rewards.canary.title": "Pametni ugovor i novčanici na testnoj mreži",
  "rewards.canary.network": "Monad testna mreža · Lanac 10143 · Samo pregled",
  "rewards.canary.intro": "Pregledaj mali pokus pametnog ugovora i njegove namjenske novčanike. Za pregled ne trebaš povezati novčanik ni prijaviti se.",
  "rewards.canary.boundary": "Uplata u novčanik nije raspodjela nagrada. Ovaj sintetički pokus odvojen je od programa lige i ne mijenja produkcijski RacesOn.",
  "rewards.canary.wrongMode": "Stanje Monada dostupno je u izdvojenom demonstracijskom portalu testne mreže. Za lokalni razvoj otvori ovu putanju na portu 3102; port 3101 koristi lokalnu simulaciju.",
  "rewards.canary.loading": "Provjera finaliziranog stanja testne mreže…",
  "rewards.canary.error": "Trenutačno stanje nije moguće potvrditi. Prethodno prikazana stanja uklonjena su. Pričekaj nekoliko sekundi pa osvježi prikaz.",
  "rewards.canary.observed": "Provjereno u finaliziranom bloku {block} · {date} (Europe/Zagreb). Ovo je snimka stanja; osvježi za novu provjeru.",
  "rewards.canary.wallets": "Namjenski testni novčanici",
  "rewards.canary.walletHelp": "Ovo su infrastrukturni novčanici, a ne novčanici natjecatelja ili klubova. Stranica čita samo javne adrese; nema pristup ključevima niti može potpisivati transakcije.",
  "rewards.canary.funder": "Uplatitelj",
  "rewards.canary.operator": "Operater ugovora",
  "rewards.canary.relayer": "Posrednik transakcija",
  "rewards.canary.contract": "Pametni ugovor za raspodjelu nagrada",
  "rewards.canary.absent": "Ugovor nije postavljen",
  "rewards.canary.unverified": "Kod je pronađen · potvrda postavljanja nije provjerena",
